class Solution {
public:
    vector<int> sameEndSubstringCount(string s, vector<vector<int>>& queries) {
        int n = s.size();
        vector<array<int, 26>> pre(n + 1);
        pre[0].fill(0);
        for (int i = 0; i < n; ++i) {
            pre[i + 1] = pre[i];
            ++pre[i + 1][s[i] - 'a'];
        }
        vector<int> ans;
        for (auto& q : queries) {
            long long total = 0;
            for (int c = 0; c < 26; ++c) {
                long long x = pre[q[1] + 1][c] - pre[q[0]][c];
                total += x * (x + 1) / 2;
            }
            ans.push_back((int)total);
        }
        return ans;
    }
};
